import { useState, useEffect, useMemo } from 'react';
import { select } from '@data-source';
import { useRouteApi } from '@route';

interface FoodItem {
  id: string;
  name: string;
  flavor: string;
  shop: string;
  area: string;
  image: string;
}

export default function PageView() {
  const { goto, back } = useRouteApi();
  const [foods, setFoods] = useState<FoodItem[]>([]);

  useEffect(() => {
    const data = select('foods');
    if (data) {
      setFoods(data as unknown as FoodItem[]);
    }
  }, []);

  const handleCardClick = (id: string) => {
    goto('/food-detail', { id });
  };

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: 'var(--bg)',
      overflowX: 'clip',
      paddingBottom: 'var(--space-8)',
    }}>
      {/* Header */}
      <header style={{
        position: 'sticky',
        top: 0,
        zIndex: 10,
        backgroundColor: 'var(--bg)',
        padding: 'var(--space-4) var(--space-4) var(--space-3)',
        display: 'flex',
        alignItems: 'center',
        gap: 'var(--space-3)',
      }}>
        <button
          data-testid="back-btn"
          onClick={back}
          aria-label="返回"
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: '36px',
            height: '36px',
            border: 'none',
            background: 'transparent',
            cursor: 'pointer',
            borderRadius: 'var(--radius-sm)',
            flexShrink: 0,
          }}
        >
          <img src="assets/icons/arrow-left.svg" alt="" width="20" height="20" />
        </button>
        <h1 style={{
          fontFamily: 'var(--font-display)',
          fontWeight: 700,
          fontSize: 'var(--text-xl)',
          color: 'var(--fg)',
          margin: 0,
          letterSpacing: '-0.01em',
        }}>
          杭州美食
        </h1>
      </header>

      {/* Ink divider under header */}
      <div style={{
        height: '1px',
        background: 'var(--ink-divider)',
        margin: '0 var(--space-4)',
      }} />

      {/* Content */}
      <main style={{
        padding: 'var(--space-4)',
      }}>
        {foods.length === 0 ? (
          <EmptyState />
        ) : (
          <FoodGrid foods={foods} onCardClick={handleCardClick} />
        )}
      </main>
    </div>
  );
}

/* ─── Sub-components ──────────────────────────────────────── */

function EmptyState() {
  return (
    <div style={{
      display: 'flex',
      flexDirection: 'column',
      alignItems: 'center',
      justifyContent: 'center',
      padding: 'var(--space-12) var(--space-4)',
      textAlign: 'center',
    }}>
      <span
        className="icon"
        style={{
          WebkitMaskImage: "url('assets/icons/utensils.svg')",
          maskImage: "url('assets/icons/utensils.svg')",
          width: '48px',
          height: '48px',
          backgroundColor: 'var(--muted)',
          marginBottom: 'var(--space-4)',
        }}
      />
      <p style={{
        fontFamily: 'var(--font-body)',
        fontSize: 'var(--text-base)',
        color: 'var(--muted)',
        margin: 0,
      }}>
        暂无美食数据
      </p>
    </div>
  );
}

interface FoodGridProps {
  foods: FoodItem[];
  onCardClick: (id: string) => void;
}

function FoodGrid({ foods, onCardClick }: FoodGridProps) {
  return (
    <div style={{
      display: 'grid',
      gridTemplateColumns: 'repeat(2, 1fr)',
      gap: 'var(--space-3)',
      minWidth: 0,
    }}>
      {foods.map((food, index) => (
        <FoodCard
          key={food.id}
          food={food}
          index={index}
          onClick={() => onCardClick(food.id)}
        />
      ))}
    </div>
  );
}

interface FoodCardProps {
  food: FoodItem;
  index: number;
  onClick: () => void;
}

function FoodCard({ food, index, onClick }: FoodCardProps) {
  const delayMs = Math.min(index * 50, 300);

  return (
    <div
      role="button"
      tabIndex={0}
      data-testid={`food-card-${food.id}`}
      onClick={onClick}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
      style={{
        backgroundColor: 'var(--surface)',
        borderRadius: 'var(--radius-md)',
        boxShadow: 'var(--card-lift)',
        overflow: 'hidden',
        cursor: 'pointer',
        display: 'flex',
        flexDirection: 'column',
        minWidth: 0,
        animation: `cardEnter var(--motion-base) var(--ease-standard) both`,
        animationDelay: `${delayMs}ms`,
      }}
    >
      {/* Image - square aspect ratio */}
      <div style={{
        position: 'relative',
        width: '100%',
        paddingTop: '100%',
        overflow: 'hidden',
        flexShrink: 0,
      }}>
        <img
          src={food.image}
          alt={food.name}
          style={{
            position: 'absolute',
            top: 0,
            left: 0,
            width: '100%',
            height: '100%',
            objectFit: 'cover',
          }}
        />
      </div>

      {/* Text content */}
      <div style={{
        padding: 'var(--space-3)',
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--space-1)',
        minWidth: 0,
        flex: 1,
      }}>
        {/* Name - single line, serif */}
        <h3 style={{
          fontFamily: 'var(--font-display)',
          fontWeight: 600,
          fontSize: 'var(--text-base)',
          color: 'var(--fg)',
          margin: 0,
          whiteSpace: 'nowrap',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
          minWidth: 0,
        }}>
          {food.name}
        </h3>

        {/* Flavor - max 2 lines */}
        <p style={{
          fontFamily: 'var(--font-body)',
          fontWeight: 400,
          fontSize: 'var(--text-xs)',
          color: 'var(--fg-2)',
          margin: 0,
          lineHeight: 1.5,
          display: '-webkit-box',
          WebkitLineClamp: 2,
          WebkitBoxOrient: 'vertical',
          overflow: 'hidden',
          minWidth: 0,
        }}>
          {food.flavor}
        </p>

        {/* Tags row */}
        <div style={{
          display: 'flex',
          flexWrap: 'wrap',
          gap: 'var(--space-1)',
          marginTop: 'var(--space-1)',
          minWidth: 0,
        }}>
          <Tag label={food.area} />
          <Tag label={food.shop} />
        </div>
      </div>
    </div>
  );
}

function Tag({ label }: { label: string }) {
  if (!label) return null;
  return (
    <span style={{
      display: 'inline-block',
      fontFamily: 'var(--font-body)',
      fontWeight: 500,
      fontSize: 'var(--text-xs)',
      color: 'var(--accent)',
      backgroundColor: 'var(--accent-subtle)',
      padding: '2px var(--space-2)',
      borderRadius: 'var(--radius-sm)',
      letterSpacing: '0.03em',
      whiteSpace: 'nowrap',
      overflow: 'hidden',
      textOverflow: 'ellipsis',
      maxWidth: '100%',
      minWidth: 0,
    }}>
      {label}
    </span>
  );
}
