import { useState, useEffect } from 'react';
import { useRouteApi } from '@route';
import { select } from '@data-source';

interface RouteItem {
  id: string;
  title: string;
  days: number;
  theme: string;
  overview: string;
  dailyPlan: string;
  attractionIds: string[];
  image: string;
}

export default function PageView() {
  const { goto, back } = useRouteApi();
  const [routes, setRoutes] = useState<RouteItem[]>([]);

  useEffect(() => {
    const data = select('routes');
    if (data) {
      setRoutes(data as RouteItem[]);
    }
  }, []);

  const handleCardClick = (id: string) => {
    goto('/route-detail', { id });
  };

  const handleBack = () => {
    back();
  };

  return (
    <div style={styles.root}>
      {/* Animation & interaction styles */}
      <style>{`
        @keyframes routeCardEnter {
          from {
            opacity: 0;
            transform: translateY(24px);
          }
          to {
            opacity: 1;
            transform: translateY(0);
          }
        }
        .route-card-enter {
          animation: routeCardEnter var(--motion-base) var(--ease-standard) both;
        }
        [data-testid="route-card"]:active {
          transform: scale(0.985);
          box-shadow: var(--card-lift), 0 0 0 1px var(--border);
        }
        [data-testid="route-card"]:focus-visible {
          outline: 2px solid var(--accent);
          outline-offset: 2px;
        }
        [data-testid="back-btn"]:active {
          transform: scale(0.96);
        }
        [data-testid="back-btn"]:focus-visible {
          outline: 2px solid var(--accent);
          outline-offset: 2px;
        }
        @media (prefers-reduced-motion: reduce) {
          .route-card-enter,
          [data-testid="route-card"],
          [data-testid="back-btn"] {
            animation-duration: 0.01ms !important;
            transition-duration: 0.01ms !important;
          }
        }
      `}</style>

      {/* Header */}
      <header style={styles.header}>
        <button
          data-testid="back-btn"
          onClick={handleBack}
          style={styles.backBtn}
          aria-label="返回"
        >
          <img
            src="assets/icons/arrow-left.svg"
            alt=""
            width={24}
            height={24}
            style={styles.backIcon}
          />
        </button>
        <h1 style={styles.pageTitle}>旅游路线</h1>
        <div style={styles.headerSpacer} />
      </header>

      {/* Route Cards */}
      <main style={styles.main}>
        {routes.length === 0 ? (
          <div style={styles.emptyState}>
            <img
              src="assets/icons/route.svg"
              alt=""
              width={48}
              height={48}
              style={styles.emptyIcon}
            />
            <p style={styles.emptyText}>暂无路线数据</p>
          </div>
        ) : (
          <div style={styles.cardList}>
            {routes.map((route, index) => (
              <RouteCard
                key={route.id}
                route={route}
                index={index}
                onClick={() => handleCardClick(route.id)}
              />
            ))}
          </div>
        )}
      </main>
    </div>
  );
}

/* ─── Sub-component: Route Card ─── */

interface RouteCardProps {
  route: RouteItem;
  index: number;
  onClick: () => void;
}

function RouteCard({ route, index, onClick }: RouteCardProps) {
  const animationDelay = `${index * 60}ms`;

  return (
    <article
      data-testid="route-card"
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
      style={{
        ...styles.card,
        animationDelay,
      }}
      className="route-card-enter"
    >
      {/* Image area with overlay */}
      <div style={styles.imageWrap}>
        <img
          src={route.image}
          alt={route.title}
          style={styles.cardImage}
          loading="lazy"
        />
        <div style={styles.imageOverlay} />

        {/* Days badge - top right */}
        <div style={styles.daysBadge}>
          <span style={styles.daysNumber}>{route.days}</span>
          <span style={styles.daysLabel}>天</span>
        </div>

        {/* Title - bottom left on image */}
        <h2 style={styles.cardTitle}>{route.title}</h2>
      </div>

      {/* Info area below image */}
      <div style={styles.infoArea}>
        {/* Theme tag */}
        <span style={styles.themeTag}>{route.theme}</span>

        {/* Overview summary - max 3 lines */}
        <p style={styles.overview}>{route.overview}</p>
      </div>
    </article>
  );
}

