// APP BRIDGE — injected by framework, used by iterate agent via web_test
// FRAMEWORK FILE — DO NOT MODIFY
/* eslint-disable */

interface RecordingCallback {
  (frame: number, state: Record<string, unknown>): unknown;
}

const channels: Record<string, () => unknown> = {};
let _recording = false;
let _rafId: number | null = null;
let _frameCount = 0;
let _recordedFrames: unknown[] = [];
let _cb: RecordingCallback | null = null;

function _collectState(): Record<string, unknown> {
  const s: Record<string, unknown> = {};
  for (const [k, fn] of Object.entries(channels)) {
    s[k] = fn();
  }
  return s;
}

(window as any).__app = {
  get version(): string {
    const scripts = document.querySelectorAll('script[type="module"]');
    for (const s of Array.from(scripts)) {
      const src = (s as HTMLScriptElement).src;
      if (src && src.includes('/assets/')) return src.split('/assets/')[1];
    }
    return 'unknown';
  },

  register(id: string, fn: () => unknown): void {
    channels[id] = fn;
  },
  unregister(id: string): void {
    delete channels[id];
  },

  get state(): Record<string, unknown> {
    return _collectState();
  },
  get(id: string): unknown {
    const fn = channels[id];
    return fn ? fn() : undefined;
  },

  startRecording(cb: RecordingCallback): () => void {
    _recording = true;
    _frameCount = 0;
    _recordedFrames = [];
    _cb = cb;

    function tick() {
      if (!_recording) return;
      const state = _collectState();
      const result = _cb!(_frameCount, state);
      if (result !== undefined) _recordedFrames.push(result);
      _frameCount++;
      _rafId = requestAnimationFrame(tick);
    }
    _rafId = requestAnimationFrame(tick);
    return () => (window as any).__app.stopRecording();
  },

  stopRecording(): void {
    _recording = false;
    if (_rafId !== null) {
      cancelAnimationFrame(_rafId);
      _rafId = null;
    }
    _cb = null;
  },

  get recordedFrames(): unknown[] {
    return _recordedFrames;
  },
  clearRecording(): void {
    _recordedFrames = [];
    _frameCount = 0;
  },
};
