import type {
  AddMarkerRequest,
  AddMarkersRequest,
  AddPolylineRequest,
  AMapLngLat,
  AMapMap,
  AMapMarker,
  AMapPolyline,
  CreateMapRequest,
  DestroyMapRequest,
  FitViewRequest,
  Result,
} from './types.js';

function normalizePosition(
  AMap: { readonly LngLat: new (lng: number, lat: number) => AMapLngLat },
  position: [number, number],
): AMapLngLat {
  return new AMap.LngLat(position[0], position[1]);
}

function getContainerElement(container: string | HTMLElement): HTMLElement | null {
  if (typeof container === 'string') {
    return document.getElementById(container);
  }
  return container;
}

function hasVisibleSize(element: HTMLElement): boolean {
  const rect = element.getBoundingClientRect();
  return rect.width > 0 && rect.height > 0;
}

/**
 * 在已加载的 AMap 命名空间上创建地图实例。
 *
 * 注意：容器在调用时必须有可见的宽高，否则高德地图无法渲染。
 * 建议在 Vue 的 onMounted 中调用，并确保容器或其祖先有明确高度（如 min-h-dvh / h-dvh）。
 */
// eslint-disable-next-line @typescript-eslint/require-await
export async function createMap(request: CreateMapRequest): Promise<Result<AMapMap>> {
  try {
    const { AMap, container, options } = request;
    const element = getContainerElement(container);
    if (!element) {
      return { ok: false, error: '地图容器元素不存在' };
    }
    if (!hasVisibleSize(element)) {
      return { ok: false, error: '地图容器无可见尺寸，请检查容器高度是否设置' };
    }

    const map = new AMap.Map(element, {
      center: options?.center ?? [116.397428, 39.90923],
      zoom: options?.zoom ?? 12,
      ...options,
    });
    return { ok: true, data: map };
  } catch (err) {
    const message = err instanceof Error ? err.message : '未知错误';
    return { ok: false, error: `创建地图实例失败：${message}` };
  }
}

/**
 * 在地图上添加单个标点。
 */
// eslint-disable-next-line @typescript-eslint/require-await
export async function addMarker(request: AddMarkerRequest): Promise<Result<AMapMarker>> {
  try {
    const { AMap, map, position, options } = request;
    const markerOptions: Record<string, unknown> = {
      position: normalizePosition(AMap, position),
      map,
      title: options?.title,
      ...options,
    };

    if (options?.label) {
      markerOptions.label = {
        content: options.label,
        direction: 'top',
      };
    }

    if (options?.icon) {
      markerOptions.icon = options.icon;
    }

    const marker = new AMap.Marker(markerOptions);
    return { ok: true, data: marker };
  } catch (err) {
    const message = err instanceof Error ? err.message : '未知错误';
    return { ok: false, error: `添加标点失败：${message}` };
  }
}

/**
 * 在地图上批量添加标点。
 */
export async function addMarkers(request: AddMarkersRequest): Promise<Result<AMapMarker[]>> {
  try {
    const { AMap, map, positions, options } = request;
    const markers: AMapMarker[] = [];
    for (const position of positions) {
      const result = await addMarker({ AMap, map, position, options });
      if (!result.ok) return result;
      markers.push(result.data);
    }
    return { ok: true, data: markers };
  } catch (err) {
    const message = err instanceof Error ? err.message : '未知错误';
    return { ok: false, error: `批量添加标点失败：${message}` };
  }
}

/**
 * 在地图上添加路线（Polyline）。
 */
// eslint-disable-next-line @typescript-eslint/require-await
export async function addPolyline(request: AddPolylineRequest): Promise<Result<AMapPolyline>> {
  try {
    const { AMap, map, path, options } = request;
    const polyline = new AMap.Polyline({
      path: path.map((p) => normalizePosition(AMap, p)),
      map,
      strokeColor: options?.strokeColor ?? '#3B82F6',
      strokeWeight: options?.strokeWeight ?? 4,
      ...options,
    });
    return { ok: true, data: polyline };
  } catch (err) {
    const message = err instanceof Error ? err.message : '未知错误';
    return { ok: false, error: `添加路线失败：${message}` };
  }
}

/**
 * 让地图自适应覆盖物范围。
 */
// eslint-disable-next-line @typescript-eslint/require-await
export async function fitView(request: FitViewRequest): Promise<Result<void>> {
  try {
    const { map, overlays } = request;
    map.setFitView(overlays);
    return { ok: true, data: undefined };
  } catch (err) {
    const message = err instanceof Error ? err.message : '未知错误';
    return { ok: false, error: `自适应视图失败：${message}` };
  }
}

/**
 * 销毁地图实例。
 */
// eslint-disable-next-line @typescript-eslint/require-await
export async function destroyMap(request: DestroyMapRequest): Promise<Result<void>> {
  try {
    request.map.destroy();
    return { ok: true, data: undefined };
  } catch (err) {
    const message = err instanceof Error ? err.message : '未知错误';
    return { ok: false, error: `销毁地图失败：${message}` };
  }
}
