/**
 * Search SDK — 网络搜索 / 网络搜图能力
 *
 * 通过 `@search-sdk` 调用 Runtime Server 的搜索服务。
 * 服务端会自动把自然语言描述简化为搜索关键词，并在多个搜索站点之间失败重试。
 *
 * ### 导出函数
 *
 * ```typescript
 * import { agent_web_search, agent_search_images } from '@search-sdk';
 * ```
 *
 * | 函数 | 用途 | 签名 | 输出 |
 * |------|------|------|------|
 * | `agent_web_search<T>` | 网页搜索 + 结构化提取 | `agent_web_search(query, schema, limit?)` | `Promise<Result<SearchExtractResponse<T>>>` |
 * | `agent_search_images` | 图片搜索 | `agent_search_images(query, limit?)` | `Promise<Result<SearchResponse<ImageSearchResult>>>` |
 *
 * `query` 直接传具体的自然语言描述（服务端自动提取关键词，无需手动分词）。
 * `schema` 是目标记录的字段定义（JSON Schema），服务端据此用 LLM 把搜索结果提取为
 * 与 **dataModel 匹配**的记录数组，可直接填进控件/数据源（如景点卡片、价格表、排行榜、链接列表）。
 * `limit` 可选，范围 1-20，默认 8。
 *
 * ### URL 可达性说明
 *
 * `agent_web_search` 返回前，服务端会对每条结果的来源链接做 HEAD/GET 可达性探测，
 * 跟随重定向并过滤掉 404/超时/不可达的链接。因此 `source_url` / `url` 字段已经过一轮
 * 可用性筛选。但探测存在以下限制：
 * - 少数站点的反爬虫策略可能让探测返回非 2xx，导致有效链接被误过滤；
 * - 探测只验证链接可达，不验证页面内容是否与摘要一致；
 * - 网络波动可能造成偶发误判。
 * 因此详情页仍建议用 `agent_extract_web_pages` 提取正文做兜底，不要把「查看原文」
 * 作为唯一内容来源。
 *
 * ### 提取能力边界（agent_web_search 的 schema 约束）
 *
 * 搜索引擎只提供标题/摘要/链接，**没有全文**。因此 schema：
 * - **只能声明摘要级字段**：title / summary / url / source_name / published_at / cover_image / category 等；
 * - **禁止声明全文字段**（content / body / full_text / article）——服务端无全文材料，必然提取为空；
 * - **必须包含 `url`（或 `source_url`）字段**（服务端保证填来源链接）：详情页需要更多内容时，
 *   展示摘要并提供「查看原文」外链（`target="_blank"`），不要在应用内求全文。
 *
 * ### Recipe 1：搜索结果 → dataModel 结构化展示
 *
 * 定义与 dataModel 对齐的 interface，把字段描述（JSON Schema）作为第二参传入，
 * 返回的 `results` 就是该类型的记录数组，可直接渲染；若 PRD dataUsages 声明
 * 本页是该数据源的 producer，也可 `insert` 进 `@data-source`。
 * 只想渲染「标题 + 摘要 + 链接」列表时，schema 就声明 `{ title, url, snippet }` 三个字段。
 *
 * ```typescript
 * import { agent_web_search } from '@search-sdk';
 *
 * interface Spot {
 *   name: string;
 *   description?: string;
 *   ticket?: string;
 *   source_url?: string;
 * }
 *
 * async function loadSpots(city: string) {
 *   const result = await agent_web_search<Spot>(
 *     `${city} 最值得去的景点推荐`,
 *     {
 *       name: 'Spot',
 *       properties: {
 *         name: { type: 'string', description: '景点名称' },
 *         description: { type: 'string', description: '一句话简介' },
 *         ticket: { type: 'string', description: '门票价格，如「免费」「60元」' },
 *         source_url: { type: 'string', description: '来源链接' },
 *       },
 *     },
 *     6,
 *   );
 *
 *   if (!result.ok) {
 *     console.error('搜索提取失败:', result.error);
 *     return;
 *   }
 *
 *   // result.data.results 是 Spot[]，直接渲染或写入数据源
 *   console.log(result.data.results);
 * }
 * ```
 *
 * schema 的字段必须是 dataModel 字段的子集描述；字段越具体（名称/含义/示例），提取越准。
 *
 * ### Recipe 2：图片与控件关联
 *
 * 图片搜索按**数据项**发起：用该项的具体字段构造 query，并行搜索后把返回的
 * URL 写回该项的图片字段，模板按框架约定条件渲染。
 *
 * ```typescript
 * import { agent_search_images } from '@search-sdk';
 *
 * interface Spot { name: string; imageUrl?: string; }
 *
 * async function bindImages(spots: Spot[]) {
 *   await Promise.all(
 *     spots.map(async (spot) => {
 *       const r = await agent_search_images(`${spot.name} 实景图`, 1);
 *       if (r.ok && r.data.results[0]) {
 *         spot.imageUrl = r.data.results[0].url; // 写回该项，控件自动关联
 *       }
 *     }),
 *   );
 * }
 * ```
 *
 *
 * 关联规则：query 必须含该项的专有名词（名称/品牌/地点）；并行发起；搜图失败保持空值
 * 并展示占位样式；**只允许使用返回列表中的 URL，禁止编造**。
 *
 * ### Recipe 3：网页搜索结果自带配图，不用再单独搜图
 *
 * `agent_web_search` 的 schema 里若声明图片/封面类字段（image/cover/thumbnail/icon），
 * 服务端会优先用搜索结果自带的缩略图或查询级图片候选填充该字段（结果没有就不填）。
 * 因此页面拿到 `cover_image` 后**直接渲染即可**，不要对每个条目再无条件调用
 * `agent_search_images`。**仅当某条 `cover_image` 为空、且确实需要配图时**，才用
 * `agent_search_images` 单独补图。
 *
 * ### Recipe 4：详情页拉取真实正文（摘要只是片段）
 *
 * 列表里的 `summary` 是搜索结果片段，**不等于原文全文**。资讯/文章详情页在挂载时
 * 用 `agent_extract_web_pages([source_url])` 拉取 source_url 的真实正文渲染；
 * 失败（未配置 scrape.do / 超时）时回退展示 `summary` + 「查看原文」外链；
 * `source_url` 为空（示例 seed）时隐藏「查看原文」并显示示例标识。
 *
 * ```typescript
 * import { agent_extract_web_pages } from '@search-sdk';
 *
 * async function loadArticle(sourceUrl: string) {
 *   const r = await agent_extract_web_pages([sourceUrl]);
 *   if (r.ok && r.data.results[0]?.ok) {
 *     return r.data.results[0].content; // 真实正文
 *   }
 *   return null; // 回退展示 summary + 查看原文
 * }
 * ```
 *
 * ### 规则
 *
 * 1. 所有调用必须有 `await`
 * 2. 必须有错误处理分支 — `if (!result.ok)` 不可省略；`result.error` 是 `string`，禁止 `instanceof Error`
 * 3. `result.data.results` 可能少于请求数量，使用前检查长度
 * 4. **禁止编造图片 URL**：`<img>` 只能使用 `agent_search_images` 返回列表中的 `url`
 * 5. 搜索结果来自公网搜索引擎，schema 必须声明 url/link 类字段承载来源链接（提取规则保证填充）
 * 6. 提取结果由 LLM 生成，渲染前对字段缺失要有兜底（可选链 / 默认值）
 */

export type Result<T> =
  | { readonly ok: true; readonly data: T }
  | { readonly ok: false; readonly error: string };

export interface ImageSearchResult {
  readonly title: string;
  readonly url: string;
  readonly thumbnailUrl?: string;
  readonly sourceUrl?: string;
  readonly width?: number;
  readonly height?: number;
}

export interface SearchResponse<T> {
  /** 原始查询 */
  readonly query: string;
  /** 服务端实际用于搜索的关键词（经简化/提取） */
  readonly keywords: string;
  /** 关键词来源：llm = LLM 提取；heuristic = 启发式清洗；passthrough = 原样使用 */
  readonly simplifiedBy: 'llm' | 'heuristic' | 'passthrough';
  /** 实际命中的搜索站点 */
  readonly provider: string;
  readonly count: number;
  /** 搜索执行时的 ISO 8601 时间戳 */
  readonly searchedAt: string;
  readonly results: T[];
}

/** 结构化提取结果：`results` 为与传入 schema 匹配的记录数组 */
export interface SearchExtractResponse<T> {
  readonly query: string;
  readonly keywords: string;
  readonly simplifiedBy: 'llm' | 'heuristic' | 'passthrough';
  readonly provider: string;
  readonly count: number;
  /** 搜索执行时的 ISO 8601 时间戳 */
  readonly searchedAt: string;
  readonly results: T[];
}

/** 单条网页正文提取结果。 */
export interface ExtractedWebPage {
  readonly url: string;
  readonly ok: boolean;
  readonly title?: string;
  readonly content?: string;
  readonly error?: string;
}

/** 网页正文提取响应。 */
export interface ExtractWebPagesResponse {
  readonly results: ExtractedWebPage[];
}

const DEFAULT_TIMEOUT_MS = 20_000;
const EXTRACT_TIMEOUT_MS = 60_000;
const EXTRACT_WEB_TIMEOUT_MS = 30_000;

/** 数据有效期 / 结果新鲜度。 */
export type Freshness = 'noLimit' | 'day' | 'week' | 'month' | 'year';

async function postSearch<T>(
  resourceType: 'web-search' | 'image-search',
  query: string,
  limit?: number,
  schema?: object,
  freshness?: Freshness,
): Promise<Result<T>> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), schema ? EXTRACT_TIMEOUT_MS : DEFAULT_TIMEOUT_MS);
  try {
    const response = await fetch('/api/v1/agent/execute', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ prompt: query, limit, schema, resourceType, freshness }),
      signal: controller.signal,
    });
    if (!response.ok) {
      return { ok: false, error: `搜索服务请求失败（HTTP ${response.status}）` };
    }
    return (await response.json()) as Result<T>;
  } catch (err) {
    if (err instanceof DOMException && err.name === 'AbortError') {
      return { ok: false, error: '搜索请求超时，请稍后重试' };
    }
    return { ok: false, error: err instanceof Error ? err.message : '网络连接失败' };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * 网页搜索 + LLM 结构化提取：返回与 `schema`（dataModel 字段定义）匹配的记录数组。
 */
export function agent_web_search<T>(
  query: string,
  schema: object,
  limit?: number,
  freshness?: Freshness,
): Promise<Result<SearchExtractResponse<T>>> {
  return postSearch('web-search', query, limit, schema, freshness);
}

export function agent_search_images(
  query: string,
  limit?: number,
  freshness?: Freshness,
): Promise<Result<SearchResponse<ImageSearchResult>>> {
  return postSearch('image-search', query, limit, undefined, freshness);
}

async function postExtract(
  urls: readonly string[],
): Promise<Result<ExtractWebPagesResponse>> {
  const controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), EXTRACT_WEB_TIMEOUT_MS);
  try {
    const response = await fetch('/api/v1/agent/execute', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ resourceType: 'web-extract', urls }),
      signal: controller.signal,
    });
    if (!response.ok) {
      return { ok: false, error: `网页提取服务请求失败（HTTP ${response.status}）` };
    }
    return (await response.json()) as Result<ExtractWebPagesResponse>;
  } catch (err) {
    if (err instanceof DOMException && err.name === 'AbortError') {
      return { ok: false, error: '网页提取请求超时，请稍后重试' };
    }
    return { ok: false, error: err instanceof Error ? err.message : '网络连接失败' };
  } finally {
    clearTimeout(timer);
  }
}

/**
 * 批量提取网页正文：输入 URL 列表，返回每条 URL 的标题与正文内容。
 * 失败条目单独标记 `ok: false` 并返回 `error`，不影响其他条目。
 */
export function agent_extract_web_pages(
  urls: readonly string[],
): Promise<Result<ExtractWebPagesResponse>> {
  return postExtract(urls);
}
