// @data-source 种子初始化：将生成期种子数据一次性写入 localStorage。
// 页面代码禁止直接使用 localStorage，统一通过 @data-source 访问。
import { seedData, sourcesMeta } from '../../data/sources';
import type { DataSourceMeta } from '@data-source-types';

let seeded = false;

/** 首次访问时把种子数据写入 localStorage（仅当该 key 为空时）。 */
export function ensureSeeded(): void {
  if (seeded) return;
  seeded = true;
  for (const [name, meta] of Object.entries(sourcesMeta)) {
    if (meta.seeded === true) {
      seedIfEmpty(name);
    }
  }
}

function seedIfEmpty(name: string): void {
  if (localStorage.getItem(name) !== null) return;
  // seedData 是 Partial<SourceDataMap>（string 无法直接索引）；name 来自 sourcesMeta 键，缺项时 initial 为 undefined
  const initial = (seedData as Record<string, unknown>)[name];
  if (initial === undefined) return;
  localStorage.setItem(name, JSON.stringify(initial));
}
