// @data-source：统一数据读写入口（底层为 localStorage）。
// 所有数据源默认支持 CURD；dev-llm-* 来源的数据会在首次访问时从 src/data/ 模块种子化到 localStorage。
// 禁止直接使用 localStorage / sessionStorage，禁止直接引用 src/data/ 数据文件（eslint 强制）。
//
// 类型契约：所有 API 的返回/参数类型由数据源名经 SourceDataMap（src/types/data-sources.ts）推导，
// 集合源（isCollect=true）映射为数组、单条源映射为单值。调用方只写数据源名，禁止显式泛型——
// 形状写错（如把单条源当数组消费）会在编译期直接报错。
//
// 静态资源路径：数据记录中的图片字段（如 cover_image）存储相对路径（如 'assets/xxx.png'），
// 由浏览器通过 <base href> 自动解析，无需手动调用 resolveAssetUrl。
import { sourcesMeta } from '../../data/sources';
import { ensureSeeded } from './seed';
import type { DataSourceMeta, SourceDataMap } from '@data-source-types';

/** 集合源名字子集：SourceDataMap[K] 为数组的 K */
type CollectKey = {
  [K in keyof SourceDataMap]: SourceDataMap[K] extends unknown[] ? K : never;
}[keyof SourceDataMap];

/** 集合源条目类型 */
type CollectItem<K extends CollectKey> = SourceDataMap[K] extends (infer E)[] ? E : never;

/** insert 的值类型：集合源传条目，单条源传整体值 */
type InsertValue<K extends keyof SourceDataMap> =
  K extends CollectKey ? CollectItem<K> : SourceDataMap[K];

/** update 的 patch 类型：集合源为条目 Partial，单条源为整体 Partial */
type PatchValue<K extends keyof SourceDataMap> =
  Partial<K extends CollectKey ? CollectItem<K> : SourceDataMap[K]>;

function metaOf(name: string): DataSourceMeta | undefined {
  const meta = sourcesMeta[name];
  if (!meta) {
    console.error(`[data-source] unknown source "${name}"`);
    return undefined;
  }
  return meta;
}

function readLocal(name: string, meta: DataSourceMeta): unknown {
  ensureSeeded();
  const raw = localStorage.getItem(name);
  if (raw === null) return meta.isCollect ? [] : undefined;
  let value: unknown;
  try {
    value = JSON.parse(raw) as unknown;
  } catch {
    return meta.isCollect ? [] : undefined;
  }
  // 形状守卫：存储值与 meta 声明矛盾恒为 bug（多为跨版本残留的 localStorage 数据），
  // 当场抛带数据源名的错误，不静默继续（静默的代价是页面运行时崩溃白屏）。
  if (meta.isCollect !== Array.isArray(value)) {
    throw new Error(
      `[data-source] source "${name}" shape mismatch: isCollect=${meta.isCollect} but stored value is ` +
        `${Array.isArray(value) ? 'array' : 'non-array'}（疑似跨版本残留的 localStorage 数据）`,
    );
  }
  return value;
}

function writeLocal(name: string, value: unknown): void {
  ensureSeeded();
  const json = JSON.stringify(value);
  try {
    localStorage.setItem(name, json);
  } catch (e) {
    if (e instanceof DOMException && e.name === 'QuotaExceededError') {
      console.warn(`[data-source] localStorage full, clearing and retrying`);
      localStorage.clear();
      localStorage.setItem(name, json);
    } else {
      throw e;
    }
  }
}

const MODIFIED_PREFIX = '_user_modified_';

function markUserModified(name: string): void {
  localStorage.setItem(MODIFIED_PREFIX + name, '1');
}

/** select：全量读。集合源返回数组，单条源返回值或 undefined（类型由数据源名推导）。 */
export function select<K extends keyof SourceDataMap>(name: K): SourceDataMap[K] | undefined {
  const meta = metaOf(name);
  if (!meta) return undefined;
  return readLocal(name, meta) as SourceDataMap[K] | undefined;
}

/** find：按该数据源的 indexKey 查单条（仅集合源可用）。 */
export function find<K extends CollectKey>(name: K, key: unknown): CollectItem<K> | undefined {
  const meta = metaOf(name);
  if (!meta) return undefined;
  if (!meta.indexKey) {
    console.error(`[data-source] source "${name}" is not indexable（需要 indexKey）`);
    return undefined;
  }
  const indexKey = meta.indexKey;
  const list = (readLocal(name, meta) as unknown[] | undefined) ?? [];
  return list.find((it) => (it as Record<string, unknown>)[indexKey] === key) as CollectItem<K> | undefined;
}

/** insert：集合源追加条目（索引值在 item 的 indexKey 字段中）；单条源整体替换。 */
export function insert<K extends keyof SourceDataMap>(name: K, item: InsertValue<K>): void {
  const meta = metaOf(name);
  if (!meta) return;
  if (meta.isCollect) {
    const list = (readLocal(name, meta) as unknown[] | undefined) ?? [];
    list.push(item);
    writeLocal(name, list);
  } else {
    writeLocal(name, item);
  }
  markUserModified(name);
}

/** update：集合源按索引合并更新条目；单条源直接合并到整体（key 忽略）。 */
export function update<K extends keyof SourceDataMap>(name: K, key: unknown, patch: PatchValue<K>): void {
  const meta = metaOf(name);
  if (!meta) return;
  if (meta.isCollect) {
    if (!meta.indexKey) {
      console.error(`[data-source] source "${name}" is not indexable（需要 indexKey）`);
      return;
    }
    const indexKey = meta.indexKey;
    const list = (readLocal(name, meta) as Array<Record<string, unknown>> | undefined) ?? [];
    writeLocal(
      name,
      list.map((item) => (item[indexKey] === key ? { ...item, ...patch } : item)),
    );
  } else {
    const current = readLocal(name, meta);
    writeLocal(name, { ...((current as object) ?? {}), ...patch });
  }
  markUserModified(name);
}

/** remove：按索引删除单条（仅集合源可用）。 */
export function remove<K extends CollectKey>(name: K, key: unknown): void {
  const meta = metaOf(name);
  if (!meta) return;
  if (!meta.indexKey) {
    console.error(`[data-source] source "${name}" is not indexable（需要 indexKey）`);
    return;
  }
  const indexKey = meta.indexKey;
  const list = (readLocal(name, meta) as Array<Record<string, unknown>> | undefined) ?? [];
  writeLocal(
    name,
    list.filter((item) => item[indexKey] !== key),
  );
  markUserModified(name);
}

/** hasUserModified：用户有没有修改过这个数据源（执行过 insert / update / remove）。 */
export function hasUserModified(name: string): boolean {
  if (!metaOf(name)) return false;
  ensureSeeded();
  return localStorage.getItem(MODIFIED_PREFIX + name) === '1';
}
