import { useEffect, useState } from 'react';
import { select } from '@data-source';
import { useRouteApi } from '@route';

interface AttractionItem {
  id: string;
  name: string;
  summary: string;
  address: string;
  openTime: string;
  ticketPrice: string;
  image: string;
  latitude: number;
  longitude: number;
}

export default function PageView() {
  const { goto, back } = useRouteApi();
  const [attractions, setAttractions] = useState<AttractionItem[]>([]);

  useEffect(() => {
    const data = select('attractions');
    if (data) {
      setAttractions(data as unknown as AttractionItem[]);
    }
  }, []);

  const handleCardClick = (id: string) => {
    goto('/attraction-detail', { id });
  };

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: 'var(--bg)',
      overflowX: 'clip',
      fontFamily: 'var(--font-body)',
      color: 'var(--fg)',
    }}>
      {/* Header */}
      <header style={{
        position: 'sticky',
        top: 0,
        zIndex: 10,
        display: 'flex',
        alignItems: 'center',
        gap: 'var(--space-3)',
        padding: 'var(--space-4)',
        backgroundColor: 'var(--bg)',
      }}>
        <button
          data-testid="back-btn"
          onClick={back}
          style={{
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            width: '36px',
            height: '36px',
            border: 'none',
            background: 'transparent',
            cursor: 'pointer',
            borderRadius: 'var(--radius-sm)',
          }}
          aria-label="返回"
        >
          <img src="assets/icons/arrow-left.svg" alt="" width="24" height="24" />
        </button>
        <h1 style={{
          margin: 0,
          fontFamily: 'var(--font-display)',
          fontSize: 'var(--text-xl)',
          fontWeight: 700,
          letterSpacing: '-0.01em',
          color: 'var(--fg)',
        }}>
          杭州景点
        </h1>
      </header>

      {/* Ink divider under header */}
      <div style={{
        height: '1px',
        background: 'var(--ink-divider)',
        margin: '0 var(--space-4)',
      }} />

      {/* List */}
      <main style={{
        padding: 'var(--space-4)',
        display: 'flex',
        flexDirection: 'column',
        gap: 'var(--space-4)',
      }}>
        {attractions.length === 0 ? (
          <div style={{
            display: 'flex',
            flexDirection: 'column',
            alignItems: 'center',
            justifyContent: 'center',
            padding: 'var(--space-12) var(--space-4)',
            color: 'var(--muted)',
            fontSize: 'var(--text-sm)',
          }}>
            <span>暂无景点数据</span>
          </div>
        ) : (
          attractions.map((item, index) => (
            <AttractionCard
              key={item.id}
              item={item}
              index={index}
              onClick={() => handleCardClick(item.id)}
            />
          ))
        )}
      </main>
    </div>
  );
}

interface AttractionCardProps {
  item: AttractionItem;
  index: number;
  onClick: () => void;
}

function AttractionCard({ item, index, onClick }: AttractionCardProps) {
  return (
    <article
      data-testid="attraction-card"
      onClick={onClick}
      role="button"
      tabIndex={0}
      onKeyDown={(e) => {
        if (e.key === 'Enter' || e.key === ' ') {
          e.preventDefault();
          onClick();
        }
      }}
      style={{
        display: 'flex',
        gap: 'var(--space-3)',
        backgroundColor: 'var(--surface)',
        borderRadius: 'var(--radius-md)',
        boxShadow: 'var(--card-lift)',
        overflow: 'hidden',
        cursor: 'pointer',
        transition: `transform var(--motion-fast) var(--ease-standard), box-shadow var(--motion-fast) var(--ease-standard)`,
        animation: `cardEntrance var(--motion-base) var(--ease-standard) both`,
        animationDelay: `${index * 60}ms`,
        minHeight: '120px',
      }}
    >
      {/* Image - 40% width */}
      <div style={{
        flex: '0 0 40%',
        minWidth: 0,
        position: 'relative',
        overflow: 'hidden',
      }}>
        <img
          src={item.image}
          alt={item.name}
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            display: 'block',
          }}
        />
      </div>

      {/* Text content - 60% */}
      <div style={{
        flex: 1,
        minWidth: 0,
        display: 'flex',
        flexDirection: 'column',
        justifyContent: 'center',
        padding: 'var(--space-3) var(--space-3) var(--space-3) 0',
        gap: 'var(--space-2)',
      }}>
        {/* Name */}
        <h2 style={{
          margin: 0,
          fontFamily: 'var(--font-display)',
          fontSize: 'var(--text-lg)',
          fontWeight: 600,
          color: 'var(--fg)',
          lineHeight: 1.3,
          whiteSpace: 'nowrap',
          overflow: 'hidden',
          textOverflow: 'ellipsis',
        }}>
          {item.name}
        </h2>

        {/* Summary - 2 line clamp */}
        <p style={{
          margin: 0,
          fontSize: 'var(--text-sm)',
          color: 'var(--fg-2)',
          lineHeight: 1.6,
          display: '-webkit-box',
          WebkitLineClamp: 2,
          WebkitBoxOrient: 'vertical',
          overflow: 'hidden',
        }}>
          {item.summary}
        </p>

        {/* Area tag placeholder - using address area info */}
        <div style={{
          display: 'flex',
          alignItems: 'center',
          gap: 'var(--space-2)',
          marginTop: 'auto',
        }}>
          <span style={{
            display: 'inline-flex',
            alignItems: 'center',
            padding: '2px var(--space-2)',
            backgroundColor: 'var(--accent-subtle)',
            borderRadius: 'var(--radius-sm)',
            fontSize: 'var(--text-xs)',
            color: 'var(--accent)',
            fontWeight: 500,
            letterSpacing: '0.03em',
          }}>
            景点
          </span>
        </div>
      </div>
    </article>
  );
}
