/**
 * @route —— 框架无关导航库（React 实现）。
 * Agent 只认本模块；禁止直接 import 'react-router-dom' 的导航 API。
 */
import { useLocation, useNavigate, useSearchParams } from 'react-router-dom';
import type { RouteApi } from './types';

/** 统一入口：组件顶部调用一次（三框架同签名）。 */
export function useRouteApi(): RouteApi {
  const navigate = useNavigate();
  const [searchParams] = useSearchParams();
  const location = useLocation();

  return {
    goto: (path, query) => {
      const qs = query && Object.keys(query).length > 0 ? `?${new URLSearchParams(query).toString()}` : '';
      navigate(`${path}${qs}`);
    },
    replace: (path, query) => {
      const qs = query && Object.keys(query).length > 0 ? `?${new URLSearchParams(query).toString()}` : '';
      navigate(`${path}${qs}`, { replace: true });
    },
    back: () => navigate(-1),
    queryParam: (key) => searchParams.get(key) ?? undefined,
    currentQuery: () => Object.fromEntries(searchParams.entries()),
    currentPath: () => location.pathname,
  };
}
