import { useState, useEffect, useRef, useMemo } from 'react';
import { useRouteApi } from '@route';
import { select, find, insert, remove } from '@data-source';
import { loadAmap, createMap, addMarker, destroyMap } from '@map-sdk';
import type { AMapMap } from '@map-sdk';
import { uuid } from '../../utils/uuid';

export default function AttractionDetail() {
  const { back, queryParam } = useRouteApi();
  const id = queryParam('id');

  const attraction = useMemo(() => {
    if (!id) return undefined;
    return find('attractions', id);
  }, [id]);

  const [favorites, setFavorites] = useState(select('user_favorites') ?? []);
  const [mapReady, setMapReady] = useState(false);
  const containerRef = useRef<HTMLDivElement>(null);
  const mapRef = useRef<AMapMap | null>(null);

  const isFavorited = useMemo(() => {
    if (!attraction) return false;
    return favorites.some((f) => f.attractionId === attraction.id);
  }, [favorites, attraction]);

  const refreshFavorites = () => {
    setFavorites(select('user_favorites') ?? []);
  };

  const handleToggleFavorite = () => {
    if (!attraction) return;
    if (isFavorited) {
      const fav = favorites.find((f) => f.attractionId === attraction.id);
      if (fav) {
        remove('user_favorites', fav.id);
      }
    } else {
      insert('user_favorites', {
        id: uuid(),
        attractionId: attraction.id,
        addedAt: new Date().toISOString(),
      });
    }
    refreshFavorites();
  };

  useEffect(() => {
    if (!attraction || !containerRef.current) return;
    let destroyed = false;

    const initMap = async () => {
      const amapResult = await loadAmap();
      if (!amapResult.ok || destroyed) return;

      const mapResult = await createMap({
        AMap: amapResult.data,
        container: containerRef.current!,
        options: {
          center: [attraction.longitude, attraction.latitude],
          zoom: 15,
        },
      });
      if (!mapResult.ok || destroyed) return;

      mapRef.current = mapResult.data;
      setMapReady(true);

      await addMarker({
        AMap: amapResult.data,
        map: mapResult.data,
        position: [attraction.longitude, attraction.latitude],
      });
    };

    initMap();

    return () => {
      destroyed = true;
      if (mapRef.current) {
        destroyMap({ map: mapRef.current });
        mapRef.current = null;
      }
    };
  }, [attraction]);

  if (!attraction) {
    return (
      <div style={{
        minHeight: '100vh',
        backgroundColor: 'var(--bg)',
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'center',
        overflowX: 'clip',
      }}>
        <p style={{ color: 'var(--muted)', fontSize: 'var(--text-base)' }}>
          --
        </p>
      </div>
    );
  }

  return (
    <div style={{
      minHeight: '100vh',
      backgroundColor: 'var(--bg)',
      overflowX: 'clip',
      position: 'relative',
      paddingBottom: 'var(--space-12)',
    }}>
      {/* Hero Image */}
      <div style={{
        position: 'relative',
        width: '100%',
        height: '40vh',
        overflow: 'hidden',
      }}>
        <img
          src={attraction.image}
          alt={attraction.name}
          style={{
            width: '100%',
            height: '100%',
            objectFit: 'cover',
            display: 'block',
          }}
        />
        {/* Mist overlay */}
        <div style={{
          position: 'absolute',
          left: 0,
          bottom: 0,
          width: '100%',
          height: '60%',
          background: 'var(--hero-mist)',
          pointerEvents: 'none',
        }} />
        {/* Back button */}
        <button
          data-testid="back-btn"
          onClick={() => back()}
          style={{
            position: 'absolute',
            top: 'var(--space-4)',
            left: 'var(--space-4)',
            width: 40,
            height: 40,
            borderRadius: 'var(--radius-pill)',
            backgroundColor: 'color-mix(in srgb, var(--surface) 80%, transparent)',
            border: 'none',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            cursor: 'pointer',
            backdropFilter: 'blur(8px)',
          }}
          aria-label="返回"
        >
          <span
            className="icon"
            style={{
              WebkitMaskImage: "url('assets/icons/arrow-left.svg')",
              maskImage: "url('assets/icons/arrow-left.svg')",
              width: 20,
              height: 20,
              backgroundColor: 'var(--fg)',
              display: 'block',
            }}
          />
        </button>
      </div>

      {/* Content area */}
      <div style={{
        padding: '0 var(--space-5)',
        marginTop: 'calc(-1 * var(--space-6))',
        position: 'relative',
      }}>
        {/* Title */}
        <h1 style={{
          fontFamily: 'var(--font-display)',
          fontWeight: 700,
          fontSize: 'var(--text-2xl)',
          color: 'var(--fg)',
          letterSpacing: '-0.01em',
          textAlign: 'center',
          margin: '0 0 var(--space-4) 0',
          lineHeight: 1.3,
        }}>
          {attraction.name}
        </h1>

        {/* Summary */}
        <p style={{
          fontFamily: 'var(--font-body)',
          fontWeight: 400,
          fontSize: 'var(--text-base)',
          color: 'var(--fg)',
          lineHeight: 1.7,
          margin: '0 0 var(--space-5) 0',
          textAlign: 'justify',
        }}>
          {attraction.summary}
        </p>

        {/* Info Card */}
        <div style={{
          backgroundColor: 'var(--surface-raised)',
          borderRadius: 'var(--radius-md)',
          padding: 'var(--space-4)',
          boxShadow: 'var(--card-lift)',
          border: '1px solid color-mix(in srgb, var(--border) 50%, transparent)',
          marginBottom: 'var(--space-5)',
        }}>
          {/* Address */}
          <div style={{
            display: 'flex',
            alignItems: 'flex-start',
            gap: 'var(--space-3)',
            marginBottom: 'var(--space-3)',
          }}>
            <span
              className="icon"
              style={{
                WebkitMaskImage: "url('assets/icons/map-pin.svg')",
                maskImage: "url('assets/icons/map-pin.svg')",
                width: 18,
                height: 18,
                backgroundColor: 'var(--muted)',
                flexShrink: 0,
                marginTop: 2,
                display: 'block',
              }}
            />
            <span style={{
              fontFamily: 'var(--font-body)',
              fontSize: 'var(--text-sm)',
              color: 'var(--fg-2)',
              lineHeight: 1.5,
              minWidth: 0,
            }}>
              {attraction.address}
            </span>
          </div>

          {/* Ink divider */}
          <div style={{
            height: 1,
            background: 'var(--ink-divider)',
            margin: 'var(--space-3) 0',
          }} />

          {/* Open Time */}
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: 'var(--space-3)',
            marginBottom: 'var(--space-3)',
          }}>
            <span
              className="icon"
              style={{
                WebkitMaskImage: "url('assets/icons/clock.svg')",
                maskImage: "url('assets/icons/clock.svg')",
                width: 18,
                height: 18,
                backgroundColor: 'var(--muted)',
                flexShrink: 0,
                display: 'block',
              }}
            />
            <span style={{
              fontFamily: 'var(--font-body)',
              fontSize: 'var(--text-sm)',
              color: 'var(--fg-2)',
              lineHeight: 1.5,
              minWidth: 0,
            }}>
              {attraction.openTime}
            </span>
          </div>

          {/* Ink divider */}
          <div style={{
            height: 1,
            background: 'var(--ink-divider)',
            margin: 'var(--space-3) 0',
          }} />

          {/* Ticket Price */}
          <div style={{
            display: 'flex',
            alignItems: 'center',
            gap: 'var(--space-3)',
          }}>
            <span
              className="icon"
              style={{
                WebkitMaskImage: "url('assets/icons/ticket.svg')",
                maskImage: "url('assets/icons/ticket.svg')",
                width: 18,
                height: 18,
                backgroundColor: 'var(--muted)',
                flexShrink: 0,
                display: 'block',
              }}
            />
            <span style={{
              fontFamily: 'var(--font-body)',
              fontSize: 'var(--text-sm)',
              color: 'var(--accent)',
              fontWeight: 600,
              fontVariantNumeric: 'tabular-nums',
              lineHeight: 1.5,
              minWidth: 0,
            }}>
              {attraction.ticketPrice}
            </span>
          </div>
        </div>

        {/* Map Section */}
        <div style={{
          borderRadius: 'var(--radius-md)',
          overflow: 'hidden',
          boxShadow: 'var(--map-frame)',
          backgroundColor: 'var(--surface-sunken)',
          position: 'relative',
        }}>
          <div
            ref={containerRef}
            style={{
              width: '100%',
              height: 280,
            }}
          />
          {!mapReady && (
            <div style={{
              position: 'absolute',
              top: 0,
              left: 0,
              width: '100%',
              height: '100%',
              display: 'flex',
              alignItems: 'center',
              justifyContent: 'center',
              backgroundColor: 'var(--surface-sunken)',
            }}>
              <span style={{
                color: 'var(--muted)',
                fontSize: 'var(--text-sm)',
                fontFamily: 'var(--font-body)',
              }}>
                --
              </span>
            </div>
          )}
        </div>
      </div>

      {/* Floating Favorite Button */}
      <button
        data-testid="favorite-btn"
        onClick={handleToggleFavorite}
        style={{
          position: 'fixed',
          bottom: 'var(--space-6)',
          right: 'var(--space-5)',
          width: 56,
          height: 56,
          borderRadius: 'var(--radius-pill)',
          backgroundColor: isFavorited ? 'var(--danger)' : 'var(--accent)',
          border: 'none',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          cursor: 'pointer',
          boxShadow: 'var(--ink-shadow)',
          transition: `transform var(--motion-fast) var(--ease-standard), background-color var(--motion-fast) var(--ease-standard)`,
          zIndex: 10,
        }}
        aria-label={isFavorited ? '取消收藏' : '收藏'}
      >
        <span
          className="icon"
          style={{
            WebkitMaskImage: isFavorited
              ? "url('assets/icons/heart-filled.svg')"
              : "url('assets/icons/heart.svg')",
            maskImage: isFavorited
              ? "url('assets/icons/heart-filled.svg')"
              : "url('assets/icons/heart.svg')",
            width: 26,
            height: 26,
            backgroundColor: 'var(--accent-on)',
            display: 'block',
          }}
        />
      </button>
    </div>
  );
}
