// FRAMEWORK FILE — DO NOT MODIFY
// App-scope isolation polyfill for localStorage / sessionStorage.
// Detects the appId from the runtime URL (/app/:appName/) and transparently
// prefixes all keys, so multiple FieldsLab apps served from the same origin
// do not share storage keys.

(function initAppScopeStorage(): void {
  if (typeof window === 'undefined') {
    return;
  }

  const appId = ((): string => {
    const match = window.location.pathname.match(/\/app\/([^/]+)/);
    return match ? match[1] : 'default';
  })();

  const PREFIX = `${appId}:`;

  function wrapStorage(storage: Storage): Storage {
    const prefixedKeys = (): string[] => {
      const keys: string[] = [];
      for (let i = 0; i < storage.length; i++) {
        const key = storage.key(i);
        if (key && key.startsWith(PREFIX)) {
          keys.push(key);
        }
      }
      return keys;
    };

    const wrapper = Object.create(Storage.prototype) as Storage;

    Object.defineProperty(wrapper, 'length', {
      get(): number {
        return prefixedKeys().length;
      },
      configurable: true,
    });

    wrapper.key = (index: number): string | null => {
      const keys = prefixedKeys();
      const fullKey = keys[index];
      return fullKey ? fullKey.slice(PREFIX.length) : null;
    };

    wrapper.getItem = (key: string): string | null => storage.getItem(PREFIX + key);
    wrapper.setItem = (key: string, value: string): void => storage.setItem(PREFIX + key, value);
    wrapper.removeItem = (key: string): void => storage.removeItem(PREFIX + key);
    wrapper.clear = (): void => {
      prefixedKeys().forEach((key) => storage.removeItem(key));
    };

    return wrapper;
  }

  try {
    Object.defineProperty(window, 'localStorage', {
      value: wrapStorage(window.localStorage),
      configurable: true,
    });
    Object.defineProperty(window, 'sessionStorage', {
      value: wrapStorage(window.sessionStorage),
      configurable: true,
    });
  } catch {
    // If the runtime prevents replacing Storage, fall back to native behavior.
  }
})();
