import { useState, useEffect } from 'react';
import { select, remove } from '@data-source';
import { useRouteApi } from '@route';

interface FavoriteWithAttraction {
  favoriteId: string;
  attractionId: string;
  name: string;
  summary: string;
  image: string;
}

export default function FavoritesPage() {
  const { goto, back } = useRouteApi();
  const [favorites, setFavorites] = useState<FavoriteWithAttraction[]>([]);
  const [loaded, setLoaded] = useState(false);

  const refreshData = () => {
    const favs = select('user_favorites') ?? [];
    const attractions = select('attractions') ?? [];
    const attractionMap = new Map(attractions.map((a) => [a.id, a]));

    const merged: FavoriteWithAttraction[] = [];
    for (const fav of favs) {
      const attr = attractionMap.get(fav.attractionId);
      if (attr) {
        merged.push({
          favoriteId: fav.id,
          attractionId: attr.id,
          name: attr.name,
          summary: attr.summary,
          image: attr.image,
        });
      }
    }
    setFavorites(merged);
    setLoaded(true);
  };

  useEffect(() => {
    refreshData();
  }, []);

  const handleRemove = (favoriteId: string) => {
    remove('user_favorites', favoriteId);
    refreshData();
  };

  const handleCardClick = (attractionId: string) => {
    goto('/attraction-detail', { id: attractionId });
  };

  const handleDiscover = () => {
    goto('/attractions');
  };

  const isEmpty = loaded && favorites.length === 0;

  return (
    <div style={styles.root}>
      {/* Header */}
      <header style={styles.header}>
        <button
          data-testid="back-btn"
          style={styles.backBtn}
          onClick={() => back()}
          aria-label="返回"
        >
          <img src="assets/icons/arrow-left.svg" alt="" width="20" height="20" />
        </button>
        <h1 style={styles.title}>我的收藏</h1>
        <p style={styles.subtitle}>
          {loaded ? `${favorites.length} 个景点` : '加载中...'}
        </p>
      </header>

      {/* Content */}
      <main style={styles.main}>
        {!loaded && (
          <div style={styles.skeletonContainer}>
            {[1, 2, 3].map((i) => (
              <div key={i} style={styles.skeletonCard}>
                <div style={styles.skeletonImage} />
                <div style={styles.skeletonText}>
                  <div style={styles.skeletonLine} />
                  <div style={{ ...styles.skeletonLine, width: '60%' }} />
                </div>
              </div>
            ))}
          </div>
        )}

        {isEmpty && (
          <div style={styles.emptyState}>
            <div style={styles.emptyIllustration}>
              <svg
                width="120"
                height="80"
                viewBox="0 0 120 80"
                fill="none"
                xmlns="http://www.w3.org/2000/svg"
              >
                {/* West Lake silhouette - simplified */}
                <path
                  d="M10 60 Q30 40 50 55 Q70 35 90 50 Q105 40 115 55"
                  stroke="var(--border)"
                  strokeWidth="1.5"
                  fill="none"
                  strokeLinecap="round"
                />
                <path
                  d="M20 65 Q40 50 60 62 Q80 48 100 58"
                  stroke="var(--muted)"
                  strokeWidth="1"
                  fill="none"
                  strokeLinecap="round"
                  opacity="0.5"
                />
                {/* Small pagoda hint */}
                <rect x="55" y="30" width="10" height="20" rx="1" fill="var(--border)" />
                <path d="M52 30 L60 22 L68 30" fill="var(--border)" />
              </svg>
            </div>
            <p style={styles.emptyText}>还没有收藏任何景点</p>
            <button
              data-testid="discover-btn"
              style={styles.discoverBtn}
              onClick={handleDiscover}
            >
              去发现景点
            </button>
          </div>
        )}

        {loaded && favorites.length > 0 && (
          <div style={styles.list}>
            {favorites.map((item, index) => (
              <FavoriteCard
                key={item.favoriteId}
                item={item}
                index={index}
                onRemove={() => handleRemove(item.favoriteId)}
                onClick={() => handleCardClick(item.attractionId)}
              />
            ))}
          </div>
        )}
      </main>
    </div>
  );
}

/* ─── Sub-component: Favorite Card ─── */

interface FavoriteCardProps {
  item: FavoriteWithAttraction;
  index: number;
  onRemove: () => void;
  onClick: () => void;
}

function FavoriteCard({ item, index, onRemove, onClick }: FavoriteCardProps) {
  const animationDelay = `${index * 60}ms`;

  return (
    <div
      style={{ ...styles.card, animationDelay }}
      className="favorite-card-enter"
    >
      <div
        style={styles.cardInner}
        role="button"
        tabIndex={0}
        data-testid={`favorite-card-${item.attractionId}`}
        onClick={onClick}
        onKeyDown={(e) => {
          if (e.key === 'Enter' || e.key === ' ') {
            e.preventDefault();
            onClick();
          }
        }}
      >
        {/* Image */}
        <div style={styles.imageWrap}>
          <img src={item.image} alt={item.name} style={styles.image} />
          {/* Heart indicator */}
          <span
            className="icon"
            style={{
              ...styles.heartIcon,
              WebkitMaskImage: "url('assets/icons/heart-filled.svg')",
              maskImage: "url('assets/icons/heart-filled.svg')",
            }}
          />
        </div>

        {/* Text content */}
        <div style={styles.cardContent}>
          <h3 style={styles.cardName}>{item.name}</h3>
          <p style={styles.cardSummary}>{item.summary}</p>
        </div>
      </div>

      {/* Remove button */}
      <button
        data-testid={`remove-favorite-${item.favoriteId}`}
        style={styles.removeBtn}
        onClick={(e) => {
          e.stopPropagation();
          onRemove();
        }}
        aria-label={`取消收藏${item.name}`}
      >
        <svg
          width="16"
          height="16"
          viewBox="0 0 16 16"
          fill="none"
          xmlns="http://www.w3.org/2000/svg"
        >
          <path
            d="M4 4L12 12M12 4L4 12"
            stroke="currentColor"
            strokeWidth="1.5"
            strokeLinecap="round"
          />
        </svg>
      </button>
    </div>
  );
}

