/* ─── Global styles injected via style tag ─── */
const styleTag = document.createElement('style');
styleTag.textContent = `
  @keyframes pulse {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.5; }
  }
  @keyframes cardEnter {
    from {
      opacity: 0;
      transform: translateY(24px);
    }
    to {
      opacity: 1;
      transform: translateY(0);
    }
  }
  .favorite-card-enter:hover [data-testid^="favorite-card"] {
    box-shadow: var(--ink-shadow);
    transform: translateY(-2px);
  }
  button[data-testid^="remove-favorite"]:hover {
    color: var(--danger);
    background-color: color-mix(in srgb, var(--danger) 10%, var(--surface));
  }
  button[data-testid="discover-btn"]:active {
    transform: scale(0.96);
  }
  @media (prefers-reduced-motion: reduce) {
    .favorite-card-enter,
    [data-testid^="favorite-card"],
    button[data-testid^="remove-favorite"],
    button[data-testid="discover-btn"] {
      animation-duration: 0.01ms !important;
      transition-duration: 0.01ms !important;
    }
  }
`;
if (!document.querySelector('[data-favorites-styles]')) {
  styleTag.setAttribute('data-favorites-styles', '');
  document.head.appendChild(styleTag);
}
