/* ------------------------------------------------------------------ */
/*  Search helper (domain-specific wrapper for search-sdk)            */
/* ------------------------------------------------------------------ */

interface SearchResultItem {
  name: string;
  description: string;
  url: string;
}

async function searchHangzhou(
  keyword: string,
  limit: number = 6,
): Promise<{ ok: true; data: SearchResultItem[] } | { ok: false; error: string }> {
  const sdkResult = await agent_web_search<SearchResultItem>(
    `${keyword} 杭州旅游`,
    {
      type: 'object',
      properties: {
        name: { type: 'string', description: '景点或美食名称' },
        description: { type: 'string', description: '简短描述' },
        url: { type: 'string', description: '来源链接' },
      },
      required: ['name', 'url'],
    },
    limit,
  );
  if (!sdkResult.ok) return sdkResult;
  return { ok: true, data: sdkResult.data.results };
}

