  // Mount: load data
  useEffect(() => {
    setAttractions(select('attractions') ?? []);
    setRoutes(select('routes') ?? []);
    setFoods(select('foods') ?? []);
  }, []);

  // Derived: featured items (first 6 attractions, first 3 routes, first 4 foods)
  const featuredAttractions = useMemo(() => attractions.slice(0, 6), [attractions]);
  const featuredRoutes = useMemo(() => routes.slice(0, 3), [routes]);
  const featuredFoods = useMemo(() => foods.slice(0, 4), [foods]);

