import {
  AMAP_JS_API_KEY,
  AMAP_JS_API_LOADER_URL,
  AMAP_JS_API_VERSION,
  AMAP_DEFAULT_PLUGINS,
  AMAP_DEFAULT_TIMEOUT_MS,
} from './config.js';
import type {
  LoadAmapOptions,
  AMapNamespace,
  Result,
} from './types.js';

interface AMapLoader {
  readonly load: (options: {
    readonly key: string;
    readonly version: string;
    readonly plugins?: readonly string[];
  }) => Promise<AMapNamespace>;
}

declare global {
  interface Window {
    AMapLoader?: AMapLoader;
  }
}

let loadPromise: Promise<Result<AMapNamespace>> | undefined;

function createScriptElement(src: string): HTMLScriptElement {
  const script = document.createElement('script');
  script.type = 'text/javascript';
  script.async = true;
  script.defer = true;
  script.src = src;
  return script;
}

function loadScript(src: string, timeoutMs: number): Promise<void> {
  return new Promise((resolve, reject) => {
    const existing = document.querySelector(`script[src="${src}"]`);
    if (existing) {
      resolve();
      return;
    }

    const script = createScriptElement(src);
    const timer = setTimeout(() => {
      reject(new Error(`加载地图脚本超时（超过 ${timeoutMs}ms）`));
    }, timeoutMs);

    script.onload = () => {
      clearTimeout(timer);
      resolve();
    };
    script.onerror = () => {
      clearTimeout(timer);
      reject(new Error('加载地图脚本失败'));
    };

    document.head.appendChild(script);
  });
}

/**
 * 加载高德 JS API。
 *
 * 同一页面多次调用会复用同一个 Promise。
 */
export async function loadAmap(options?: LoadAmapOptions): Promise<Result<AMapNamespace>> {
  if (typeof window === 'undefined') {
    return { ok: false, error: '地图 SDK 仅在浏览器环境可用' };
  }

  if (window.AMap) {
    return { ok: true, data: window.AMap };
  }

  if (loadPromise) {
    return loadPromise;
  }

  loadPromise = (async (): Promise<Result<AMapNamespace>> => {
    try {
      if (options?.securityConfig?.securityJsCode) {
        const globalWindow = window as unknown as Window & Record<string, unknown>;
        globalWindow._AMapSecurityConfig = {
          securityJsCode: options.securityConfig.securityJsCode,
        };
      }

      await loadScript(AMAP_JS_API_LOADER_URL, options?.timeout ?? AMAP_DEFAULT_TIMEOUT_MS);

      if (!window.AMapLoader) {
        return { ok: false, error: '高德 JS API Loader 未正确初始化' };
      }

      const AMap = await window.AMapLoader.load({
        key: options?.key ?? AMAP_JS_API_KEY,
        version: options?.version ?? AMAP_JS_API_VERSION,
        plugins: options?.plugins ?? AMAP_DEFAULT_PLUGINS,
      });

      return { ok: true, data: AMap };
    } catch (err) {
      const message = err instanceof Error ? err.message : '未知错误';
      return { ok: false, error: `地图加载失败：${message}` };
    }
  })();

  return loadPromise;
}
