import { useEffect, useState } from 'react';
import { useRouteApi } from '@route';
import { find } from '@data-source';

export default function FoodDetailPage() {
  const { back, queryParam } = useRouteApi();
  const id = queryParam('id');

  const [food, setFood] = useState<ReturnType<typeof find<'foods'>> | null>(null);

  useEffect(() => {
    if (id) {
      const record = find('foods', id);
      setFood(record ?? null);
    }
  }, [id]);

  return (
    <div style={styles.root}>
      {/* Back Button */}
      <header style={styles.header}>
        <button
          type="button"
          data-testid="back-btn"
          onClick={() => back()}
          style={styles.backBtn}
          aria-label="返回"
        >
          <img src="assets/icons/arrow-left.svg" alt="" width="24" height="24" />
        </button>
        <span style={styles.headerTitle}>美食详情</span>
        <span style={{ width: 24 }} />
      </header>

      {!food ? (
        <div style={styles.emptyState}>
          <p style={styles.emptyText}>未找到该美食记录</p>
        </div>
      ) : (
        <article style={styles.article}>
          {/* Hero Image - Square 1:1 with frame effect */}
          <div style={styles.imageFrame}>
            <img
              src={food.image}
              alt={food.name}
              style={styles.heroImage}
            />
            {/* Area Tag floating on image */}
            <span style={styles.areaTag}>{food.area}</span>
          </div>

          {/* Content Section */}
          <div style={styles.content}>
            <h1 style={styles.title}>{food.name}</h1>

            {/* Flavor Description */}
            <p style={styles.flavor}>{food.flavor}</p>

            {/* Ink Divider */}
            <div style={styles.inkDivider} />

            {/* Shop Recommendation Card */}
            <div style={styles.shopCard}>
              <div style={styles.shopIconWrap}>
                <img
                  src="assets/icons/utensils.svg"
                  alt=""
                  width="20"
                  height="20"
                  style={styles.shopIcon}
                />
              </div>
              <div style={styles.shopInfo}>
                <span style={styles.shopLabel}>推荐店铺</span>
                <span style={styles.shopName}>{food.shop}</span>
              </div>
            </div>
          </div>
        </article>
      )}
    </div>
  );
}

